******************************************************************************** MacRez.asm** (C)  Copyright Apple Computer, Inc. 1991-92* All rights reserved.** by Jim Mensch* 5/22/90** This file contains routines to read data from a mac resource fork. It is  * read only at this	point** The external interface for reading generic mac resources is a single routine* The pascal declaration for this routine is:** Function ReadResource(var theRezType:RezType; *	    theRezID:integer; theFileName:ptr):handle;* The parameters are:* theRezType - a longword usually containing a 4 byte literal that is the *	type of the resource. (On the mac it is traditional to use* 	mnemonic representation for types, like 'STR ' resources*	contain pascal strings (NOTE the space, all these literals must*	be exactly 4 bytes long...)* theRezID - an integer specifying which resource of a given type to load* theFileName - a pointer to a string containing the name of the mac resource file to read** The result of this function is a handle that contains the data in the mac resource* you must always keep in mind that the macintosh stores multiple byte quantities* backwards from the IIgs, so it you read in a 'RECT' resource from the mac you will* have to reverse the contents of the 4 word (a rectangle is 4 words you know) yourself* since I had to do this quite often to read the mac resource map, I wrote some useful* macros that do this for you (sometimes it is hard to remember which byte goes * where.** Due to the limited use of the data in mac resources, this routine is designed to* take up as little memory as it can by not leaving the resource file and map open* and loaded into memory. If you wanted to use this routine extensivly it would be* a good idea to cache the contents of the resource map for subsequent calls.** Also included in this file is a routine that reads a macwrite 5.0 file into memory* converting the text and some style information into Apple II machine readable form* it is used in connection with another file MWRead.p which has a pascal routine that * accepts the data from the macwrite data readers included here and massages it so it can * be used with GS textedit.** This code is very similar to that used in teachGS for reading Macwrite files. If you* wish to incorporate reading macwrite files into commercial products you should notify* Claris of your intent (they have a big list they keep updated), after all if* Macwrite II can read Appleworks files, should some apple IIgs app read macwrite files?**	print   push	print   off	Include 'M16.GSOS'	Include 'M16.Memory'	Include 'E16.dialog'	Include 'Teach.Macros'	Import MyMemoryID	Import ThisError	print   pop**** Modification History:** Version 1.0   Mensch*********************************************************************************** The following are the data structures in a mac resource fork. NOTE: These data* structures are from inside mac volume 1 and could change at a moments notice.*ResourceHeader	Record 0OffsetToRezData	ds.L 1OffsetToRezMap	ds.L 1LengthOfRezData	ds.L 1LengthOfRezMap	ds.L 1	EndR	ResourceDataItem	Record 0LengthOfThisItem	ds.L 1ThisItemData	ds.B 1	EndR	ResourceMapHeader	Record 0	ds.B 16	; unused	ds.B 4	; reserved	ds.B 2	; file ref numberResourceFileAttr	ds.W 1	; attributes of this resource fileOffsetToTypeList	ds.W 1OffsetToNameList	ds.W 1	EndRResourceTypeItem	Record 0TypeItemType	ds.L 1TypeItemNum	ds.W 1	; number of this typeTypeItemOffset	ds.W 1	EndR	ResourceRefList	Record 0ItemID	ds.W 1ItemNameOffset	ds.W 1ItemAttributes	ds.B 1ItemDataOffset	ds.B 3	ds.B 4	; reserved.	EndR	ResourceNameItem	Record 0Length	ds.B 1ASCIIDATA	ds.B 1	EndR	MacRezGlobals	RecordCurRezHead	ds ResourceHeaderCurMapHead	ds ResourceMapHeaderFirstTypeList	ds.W 1	; number of types to search for.CurTypeList	ds ResourceTypeItem	; NOTE: The following two items use the sameCurRefList	ds ResourceRefList	; work area! This is done to save space	ds.B 248	; fill out this table so we can read a few at a timeTheRezSize	ds.L 1FileRefNum	ds.W 1OpenBlock	dc.W 4	; use only 4 parametersOpenRefNum	ds.W 1OpenPathName	dc.L MyPathBufferReqAccess	dc.W 1	; open read onlyResNum	dc.W 1	; open the resource forkReadBlock	dc.W 4	;ReadRefNum	ds.W 1ReadDataBuf	ds.L 1ReadReqCount	ds.L 1xferCount	ds.L 1CloseBlock	dc.W 1CloseRefNum	ds.W 1SetMarkBlock	dc.W 3SMRefNum	ds.W 1SMBase	dc.W 0	; always relative to file startdisplacement	ds.L 1MyPathBuffer	ds.W 1	ds.B 256	EndR	********************************************************************************* Direct page equates used with this routine.*WorkArea	equ 1Deref	equ WorkArea+4OldDBank	equ Deref+4OldDPage	equ OldDBank+1theRTL	equ OldDPage+2theFileName	equ theRTL+3theRezID	equ theFileName+4theRezType	equ theRezID+2resultHandle	equ theRezType+4******************************************************************************** Macros to be used throughout this library*	MACRO&Lab	LongSwap &Arg&Lab	lda &Arg	pha	lda &Arg+2	xba	sta &Arg	pla	xba	sta &Arg+2	EndM		MACRO&Lab	LongSwapXY&Lab	xba	pha	txa	xba	plx	EndM		MACRO&Lab	IntSwap &Arg&Lab	lda &Arg	xba	sta &Arg	EndM		EJECT********************************************************************************OpenRezFile	PROC** Description:	This routine will open the requested RezFile*** Inputs:	Direct page pointer set up for the pathname** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	lda <theFileName	sta openPathName	lda <theFileName+2	sta openPathName+2		lda #1	sta ResNum	; reset file for reading resources		_openGS OpenBlock	bcs @done	lda OpenRefNum	sta SMRefNum	sta CloseRefNum	sta ReadRefNum	sta FileRefNum@Done	rts	EndP		EJECT********************************************************************************CloseRezFile	PROC** Description:	just closes the file!*** Inputs:	None** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	_CloseGS CLoseBlock	rts	EndP		EJECT********************************************************************************SetRezMark	PROC** Description:	sets the mark of the current file to whereever <A><X> point*** Inputs:	<A><X> point to the new mark** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	sta displacement	stx displacement+2	_SetMarkGS SetMarkBlock	rts	EndP		EJECT********************************************************************************ReadRezData	PROC** Description:	reads the proper amount of resource data into the buffer*	indicated. *** Inputs:	<A><X> contain the buffer pointer to read into*	<Y> the amount of data to read** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	sta ReadDataBuf	stx ReadDataBuf+2	sty ReadReqCount	stz ReadReqCount+2	_ReadGS ReadBlock	rts	EndP		EJECT********************************************************************************ReadRezDataLong	PROC** Description:	reads the proper amount of resource data into the buffer*	indicated. *** Inputs:	<A><X> contain the buffer pointer to read into*	<Y> the amount of data to read** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	sta ReadDataBuf	stx ReadDataBuf+2	lda theRezSize	sta ReadReqCount	lda theRezSize+2	sta ReadReqCount+2	_ReadGS ReadBlock	rts	EndP		EJECT********************************************************************************FixResourceHeader	PROC** Description:	This routine will adjust the longint in the resource header*	so that they can be used on the IIGS*** Inputs:	CurRezHead contains the current resource header to swap** Outputs:	CurRezHead will be usefull** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	LongSwap CurRezHead.OffsetToRezData	LongSwap CurRezHead.OffsetToRezMap	LongSwap CurRezHead.LengthOfRezData	LongSwap CurRezHead.LengthOfRezMap	rts	EndP	********************************************************************************FixMapHead	PROC** Description:	This routine will adjust the data in the resource map header*	so that they can be used on the IIGS*** Inputs:	CurMapHead contains the current resource map header to swap** Outputs:	CurMapHead will be usefull** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	IntSwap CurMapHead.ResourceFileAttr	IntSwap CurMapHead.OffsetToTypeList	IntSwap CurMapHead.OffsetToNameList	rts	EndP		EJECT********************************************************************************GetTheHeader	PROC** Description:	This routine will read the resource header file a resource file*** Inputs:	None** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals		jsr OpenRezFile	; open the file for reading	bcs @ErrorDone	ldy #16	; size of the header	ldax #CurRezHead	jsr ReadRezData	bcs @Error1	jsr FixResourceHeader	clc	@ErrorDone	sta >ThisError	rts	@Error1	sta >ThisError	jsr CloseRezFile	sec	rts	EndP		EJECT********************************************************************************FindRefList	PROC** Description:	Locate the referenceList for the passed rez type that we are*	looking at.*** Inputs:	File should be open and theTypeID should be set** Outputs:	WorkArea points to the reflist for this type** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	; Position file to resource map and read the map header	ldax CurRezHead.OffsetToRezMap	jsr  SetRezMark	bcsl @ErrDone		ldax #CurMapHead	ldy  #$1C	; size of the map header	jsr  ReadRezData	bcsL @ErrDone	jsr  FixMapHead;; Now that we have the map header get the first entry in the type list	ldax CurRezHead.OffsetToRezMap	clc	adc  CurMapHead.OffsetToTypeList	bcc  @1	inx@1	stax WorkArea	; save this file position for later	jsr  SetRezMark	; position the file to the start of the map list	bcs  @ErrDone	ldax #FirstTypeList	ldy  #$0A	; just read the size of the list and the offset	jsr  ReadRezData	bcs  @ErrDone	intSwap FirstTypeList	ldx  #0	; test the first entry to see if we match	jsr  MatchTypeListEntry	bcs  @FoundTheType	; if the types match we found it!@Loop	lda  FirstTypeList	beq  @NotFound	; if its zero here its not found	cmp  #$20	; number of types we can read at once	bge  @Loop005	asl  a	; else just finish the list	asl  a	asl  a	; (they are 8 bytes each...)	bra  @Loop010@Loop005	lda  #256@Loop010	tay	; amount of data to read	ldax #CurTypeList	jsr  ReadRezData	bcs  @ErrDone	jsr  MatchTypeList	; match the type list entries	bcs  @FoundTheType	lda  FirstTypeList	sec	sbc  #20	sta  FirstTypeList	bpl  @Loop@NotFound	sec	rts@FoundTheType	lda  CurTypeList,x	; move the found entry to be the first entry	sta  CurTypeList	lda  CurTypeList+2,x	sta  CurTypeList+2	lda  CurTypeList+4,x	xba	; adjust these values	sta  CurTypeList+4	lda  CurTypeList+6,x	xba	; since we will need them!	sta  CurTypeList+6	lda  WorkArea	clc	adc  CurTypeList.TypeItemOffset	sta  WorkArea	bcc  @3	clc	inc  WorkArea+2@3	rts@ErrDone	jsr  CloseRezFile	sec	rts;; The next routine will compare the typeListEntry pointed to by <X> to the ; theRezType variable and return with the carry set if it matches.MatchTypeListEntry	lda theRezType	cmp CurTypeList.TypeItemType,x	bne @NoMatch	lda theRezType+2	cmp CurTypeList.TypeItemType+2,x	bne @NoMatch	sec	rts@NoMatch	clc	rts;; This routine will run the entire type list and determine if any of its entries match; the requested typeMatchTypeList	ldx #0	ldy #0@Loop	jsr MatchTypeListEntry	bcs @GotMatch	iny	cpy #20	; are we done here?	bge @NoMatch	cpy FirstTypeList	; are we at the end of the file data?	bge @NoMatch	tya	asl a	asl a	asl a	tax	; set new data pointer	bra @Loop@NoMatch	clc@GotMatch	rts	EndP		EJECT********************************************************************************FindRezData	PROC** Description:	Locate the data we want for the passed rez ID that we are*	looking at. This routine relies on the rest of the data*	being set up*** Inputs:	File should be open and theTypeID should be set*	FindRefList should have been run and the first item*	in the type list should be set. Also, the file offset*	to the ref list should be in WorkArea** Outputs:	WorkArea points to the data in the data area** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	; Position file to reference LIst for the type that I found	ldax WorkArea	jsr  SetRezMark	bcsl @ErrDone	@Loop	lda  CurTypeList.TypeItemNum	cmp  #$0F	bge  @Loop010	; we are bigger than the max	inc  a	asl  a	; number of items times 12	asl  a	pha	asl  a	clc	adc  1,s	plx	bra  @Loop020@Loop010	lda  #$10*12@Loop020	tay	ldax #CurRefList	jsr  ReadRezData	bcs  @ErrDone; Now that we have some ref list data, lets scan it	jsr  MatchRefList	; match the type list entries	bcs  @FoundTheRef	lda  CurTypeList.TypeItemNum	sec	sbc  #$10	sta  CurTypeList.TypeItemNum	bpl  @Loop@NotFound	sec	rts@FoundTheRef	lda  CurRefList.ItemAttributes,x	; move the found entry to be the first entry	and  #$FF00	xba	sta  WorkArea+2	lda  CurRefList.ItemAttributes+2,x	; move the found entry to be the first entry	xba	sta  WorkArea	clc	adc  CurRezHead.OffsetToRezData	sta  WorkArea	bcc  @3	inc  WorkArea+2	clc@3	rts@ErrDone	sta  >ThisError	jsr  CloseRezFile	sec	rts;; The next routine will compare the typeListEntry pointed to by <X> to the ; theRezType variable and return with the carry set if it matches.MatchRefListEntry	lda theRezID	cmp CurRefList.ItemID,x	bne @NoMatch	sec	rts@NoMatch	clc	rts;; This routine will run the entire type list and determine if any of its entries match; the requested typeMatchRefList	ldx #0	ldy #0@Loop	jsr MatchRefListEntry	bcs @GotMatch	iny	cpy #$10	; are we done here?	bge @NoMatch	cpy CurTypeList.TypeItemNum ; are we at the end of the file data?	beq @fudge1	; if they are equal we better go around again!	bge @NoMatch@fudge1	tya	asl a	asl a	pha	asl a	clc	adc 1,s	plx	tax	; set new data pointer	bra @Loop@NoMatch	clc@GotMatch	rts	EndP		EJECT********************************************************************************LoadThisRez	PROC** Description:	This routine will read the resource from disk.*** Inputs:	WorkArea contains the file offset to the data we want to read** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals		ldax WorkArea	; get the proper offset	jsr  SetRezMark	; position correctly in the file	bcs  @ErrorEnd	ldy  #4	; now read the size of this resource	ldax #TheRezSize	jsr ReadRezData	bcs  @ErrorEnd	longSwap theRezSize	; turn it into usefull data	; allocate memory for this resource..	ldx #0	phx	; resultSpace	phx	PushLong theRezSize	lda >MyMemoryID	pha	phx	; attributes	phx	; locationptr	phx	_NewHandle	plx	ply	bcs @ErrorEnd	stx deref	sty deref+2	stx resultHandle	sty resultHandle+2	; now simply read in this resource data	ldy #2	lda [deref],y	tax	lda [deref]	jsr ReadRezDataLong	bcs @ErrorEnd2; we read the resource guess we are done!	clc	rts@ErrorEnd		sta >ThisError@ErrorEnd1	jsr CloseRezFile	sec	rts@ErrorEnd2		sta >ThisError	pushlong deref	_DisposeHandle	stz resultHandle+1	bra @ErrorEnd1	EndP		EJECT********************************************************************************ReadResource	PROC Export* Function ReadResource(theRezType:var RezType; theRezID:integer; theFileName:ptr):handle;* Description:	reads a given resource*** Inputs:	On stack** Outputs:	on stack** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals  	phd	; save old dpage and bank	phb		pha	pha	pha	pha		tsc	tcd	; set up our stack frame		phk	; set up our data banl	plb		stz resultHandle	; zero out the result	stz resultHandle+2	lda #0	sta >ThisError	; and zero out the error code		IntSwap theRezID	; since they are swapped on disk		jsr GetTheHeader	; open the file and read the header	bcs CallFinished	jsr FindRefList	; locate the Type in the file and move to its ref	bcs CallFinished	jsr FindRezData	; we now have the ref list, time to locate the data	bcs CallFinished; If we get here work area has the offset into the resource file data area to our; resource data record. All we need to do now is to read it in!	jsr LoadThisRez	bcs CallFinished	jsr CloseRezFile; Undo the stack stuffCallFinished	pla	pla	pla	pla		plb	pld	longa off	sep #$20	pla	ply		plx	plx	plx	plx	plx		phy	pha		longa On	rep #$20	rtl	EndP	*********************************************************************************************************************************************************************************  Read MacWrite File stuff   **********************************************************************************************************************************************************************************************************************************************************************************;WorkArea	equ 1;Deref	equ WorkArea+4;OldDBank	equ Deref+4;OldDPage	equ OldDBank+1;theRTL	equ OldDPage+2;theFileName	equ theRTL+3theStyleHandle	equ theFileName+4theDecryptKey	equ theStyleHandle+4resultText	equ theDecryptKey+4********************************************************************************ParagraphArray	Record 0ParagraphFlag	ds.W 1Paragraphlocation	ds.W 1ParagraphHandle	ds.L 1ParagraphPos	ds.L 1ParagraphDataLen	ds.W 1ParagraphFormats	ds.W 1	EndR	WindowVars	Record 0SelStart	ds.L 1SelEnd	ds.L 1VOffset	ds.W 1Redraw	ds.W 1InfoArrayPos	ds.L 1InfoArrayLength	ds.W 1LineHeightPos	ds.L 1LineHeightLength	ds.W 1PageIcon	ds.L 1DateIcon	ds.L 1TimeIcon	ds.L 1	ds.L 1OvalRedraw	ds.B 1LastOvalUpdate	ds.B 1ActiveStyle	ds.W 1ActiveFont	ds.W 1; Note the following field really ain't here on disk!NumParagraphs	ds.W 1	EndR	MacWriteGlobals	RecordtheDataSize	ds.L 1MainArrayHandle	ds.L 1	ds.W 1myDecriptKey	ds.B 16	ds.W 1tempBuffer	ds.B 256StyleHandle	ds.L 1	; holder for our style informationStyleOffset	ds.W 1	; and the current offset into it!StyleSize	ds.W 1MainData	ds WindowVars	EndR		EJECT********************************************************************************OpenFile	PROC** Description:	This routine will open the requested RezFile*** Inputs:	Direct page pointer set up for the pathname** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	lda <theFileName	sta openPathName	lda <theFileName+2	sta openPathName+2	lda #0	sta ResNum		_openGS OpenBlock	bcs @done	lda OpenRefNum	sta SMRefNum	sta CloseRefNum	sta ReadRefNum	sta FileRefNum@Done	rts	EndP		EJECT********************************************************************************CloseFile	PROC** Description:	just closes the file!*** Inputs:	None** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals		_CloseGS CLoseBlock	rts	EndP		EJECT********************************************************************************SetMark	PROC** Description:	sets the mark of the current file to whereever <A><X> point*** Inputs:	<A><X> point to the new mark** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	sta displacement	stx displacement+2	_SetMarkGS SetMarkBlock	rts	EndP		EJECT********************************************************************************ReadData	PROC** Description:	reads the proper amount of resource data into the buffer*	indicated. *** Inputs:	<A><X> contain the buffer pointer to read into*	<Y> the amount of data to read** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	sta ReadDataBuf	stx ReadDataBuf+2	sty ReadReqCount	stz ReadReqCount+2	_ReadGS ReadBlock	rts	EndP		EJECT********************************************************************************ReadDataLong	PROC** Description:	reads the proper amount of resource data into the buffer*	indicated. *** Inputs:	<A><X> contain the buffer pointer to read into*	<Y> the amount of data to read** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals	With MacWriteGlobals		sta ReadDataBuf	stx ReadDataBuf+2	lda theDataSize	sta ReadReqCount	lda theRezSize+2	sta theDataSize+2	_ReadGS ReadBlock	rts	EndP		EJECT********************************************************************************GetMainArrayInfo	PROC** Description:	This procedure will fill the info record with all the proper*	data for the main data array (actual document text)*** Inputs:	File be open** Outputs:	Main data info all set!** External Refs:** Entry Points:********************************************************************************	with MacWriteGlobals	With MacRezGlobals	; first read in the file header so we can test the version and get the paragraph info	ldy  #40		ldax #tempBuffer	jsr  ReadData	bcsL @ErrorEnd	lda  tempBuffer	; test the version info	xba	cmp  #6	; version 6???	beq  @0010	lda  #1	brl  @ErrorEnd@0010	lda  tempBuffer+2	; get the number of Paragraphs in main	xba	sta  MainData.NumParagraphs		ldx  #0	lda  #252	; location of main window data!	jsr  SetMark	bcsL @ErrorEnd		ldy  #45	; size of window vars	ldax #MainData	jsr  ReadData	bcsL @ErrorEnd;; We now have the window vars loaded, and its time to swap all the values that need swapping	LongSwap MainData.SelStart	LongSwap MainData.SelEnd	LongSwap MainData.InfoArrayPos	IntSwap MainData.InfoArrayLength	LongSwap MainData.LineHeightPos	IntSwap MainData.LineHeightLength	clc	rts	@ErrorEnd	sta >ThisError	jsr CloseFile	sec	rts		EJECT********************************************************************************ReadMainArray	PROC** Description:	This routine will load in the main text paragraph array*	information and fix it so that all its internal pointers*	are correct.*** Inputs:	None** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacWriteGlobals	With MacRezGlobals; First we need to get storage space for the data	ldx #0	phx	phx	phx	; put the size on the stack	lda MainData.InfoArrayLength	pha	lda >MyMemoryID	; CHANGE ME!!	pha	pea #$4000	; lock this puppy	phx	phx	_NewHandle	plx	ply	bcsL @ErrEnd	stx deref	sty deref+2	stx MainArrayHandle	sty MainArrayHandle+2		ldy #2	; deref the new handle	lda [deref],y	sta workArea+2	lda [deref]	sta WorkArea; and now read in the data	ldax MainData.InfoArrayPos	jsr  SetMark		ldy  MainData.InfoArrayLength	ldax WorkArea	jsr  ReadData	bcsL @ErrEnd	; Now that thats all read in, lets convert all the entries to something we can use!	ldy  #0@Loop	jsr  FixArrayEntry	tya	; now bump our index	clc	adc  #$0010	tay	cmp  MainData.InfoArrayLength	blt  @Loop	; see if we are done, if not do the next one!	; the data is now all converted to usefull form!	clc	rts@ErrEnd	sta >ThisError	jsr CloseFile	sec	rts;; This routine will adjust all the numbers in the array entries so that we can use them; later onFixArrayEntry	phy	; save the current <Y>	lda [WorkArea],y	; adjust the paragraph height field	xba	sta [WorkArea],y	tya	clc	adc #8	tay	lda [WorkArea],y	; paragraph data offset	xba	tax	iny	iny	lda [workArea],y	xba	sta deref	txa	sta [workArea],y	dey	dey	lda deref	sta [workArea],y	iny	iny	iny	iny	lda [workArea],y	; paragraph data length	xba	sta [workarea],y	ply	rts	EndP		EJECT********************************************************************************ReadTheText	PROC** Description:	This routine will read the actual paragraph records*	from a macwrite file and decompress where needed and stow into*	a data file.*** Inputs:	None** Outputs:	None** External Refs:** Entry Points:********************************************************************************	With MacWriteGlobals	With MacRezGlobals	MainArrayPtr	equ WorkAreaResultPtr	equ theFileName	; resuse the file name long on the stackSourcePtr	equ theDecryptKey	; reuse the decription key pointer..theStylePtr	equ theStyleHandle	; reuse the handle for pointer space..	ldx #0	phx	phx	phx	phx	lda >MyMemoryID	pha	phx	phx	phx	_NewHandle	; create a new text record handle	plx	ply	bcsL @ErrEnd	stx ResultText	sty ResultText+2	; pass a handle back!; Now create a work handle to use	ldx #0	phx	phx	phx	pea $1000	; a pretty good size for scratch data..	lda >MyMemoryID	pha	phx	phx	phx	_NewHandle	plx	ply	bcsL @ErrEnd	stx ScratchHandle	sty ScratchHandle+2	; and finally the style handle..	ldax theStyleHandle	stax StyleHandle	jsr  derefIt	stax theStylePtr	stz  StyleOffset; and now that we have the three handles that we need lets init our data for this routine; and get under way!	stz RulerFlag	; no ruler read in yet!	stz CurrentTextOffset	stz CurrentTextOffset+2	stz ResultSize	stz ResultSize+2	stz CurrentParaOffset	lda #$1000	sta ScratchareaSize	ldy #$10	; copy the decription key over now!@Loop1	lda [theDecryptKey],y	sta myDecriptKey-1,y	dey	dey	bpl @Loop1		ldx MainArrayHandle	ldy MainArrayHandle+2	stx deref	sty deref+2		ldy #2	; deref the new handle	lda [deref],y	sta MainArrayPtr+2	lda [deref]	sta MainArrayPtr@Loop	; first see if we should use this paragraph	ldy CurrentParaOffset	lda [MainArrayPtr],y	beq @ReadRuler	; if zero its a ruler	bmi @NextPara	; negative means its a picture	jsr ReadThisParagraph	bcs @ErrEnd	jsr AddThisParagraph	bcs @ErrEnd	jsr AddThisStyleInfo ; we now add the style info for the paragraph	bcs @ErrEnd@NextPara	lda  CurrentParaOffset	clc	adc  #$0010	tay	sty  CurrentParaOffset	cmp  MainData.InfoArrayLength	blt  @Loop	; see if we are done, if not do the next one!	clc	; we are done, we must have all the text	rts@ReadRuler;; We come here to read any ruler data. NOTE that we only read the first ruler; because we only support the one!	lda RulerFlag	bne @NextPara	; if the flag is set we already read in a ruler!	dec a	sta RulerFlag	; signal we read the first ruler..	jsr ReadThisParagraph ; load in the ruler data..	bcs @ErrEnd; now copy the ruler data into our handle..; Stylehandle is set to the proper size and SourcePtr points to the just read data	ldy #34	jsr SetStyleHandleSize	ldy #0@RulerCopy	lda [SourcePtr],y	; start reading the data	xba	; its all bytes so we can swap it!	sta [theStylePtr],y	iny	iny	cpy #34	blt @RulerCopy	ldy #30	; zero out the style count!	lda #0	sta [theStylePtr],y	brl @NextPara@ErrEnd	brl LocalError;;AddThisStyleInfo; This routine will add the style info for this paragraph to the style list that; we are creating. It ought to work real groovy (maybe it will!) This routine; relys on CurrentTextOffset being set to the start of the current paragraph; it also relys on ThisParaStyleStart being set;; First adjust ThisparaStyleStart	lda ThisParaStyleStart	lsr a	; test the low bit	bcc @ItsFine	; if its zero offset is fine!	inc ThisParaStyleStart@ItsFine	ldy ThisParaStyleStart	lda [sourcePtr],y	; get the size of the style array..	xba	sta ThisParaStyleSize	inc ThisParaStyleStart ;position to the start of the style info..	inc ThisParaStyleStart; Now loop thru and read the styles..@Loop	lda ThisParaStyleSize ; see if we are done yet..	beq @StyleLoopEnd	bmi @StyleLoopEnd	; MUST positive...	sec	sbc #6	; strip off the current style from the length	sta ThisParaStyleSize; grow our style handle to contain the proper style data..	lda styleSize	; get the current size of the style handle..	sta StyleOffset	; save it..	clc	adc #8	; room for another style..	tay	jsr SetStyleHandleSize; bump the number of style entries by 1..	ldy #30	lda [theStylePtr],y	inc a	sta [theStylePtr],y		ldy ThisParaStyleStart	tya	; now bump this by a Style record..	clc	adc #6	sta ThisParaStyleStart	lda [sourcePtr],y	xba	sta tempBuffer	iny	iny	lda [SourcePtr],y	xba	; we store it style#,font size..	and #$3F1F	; clip style and size info	sta tempBuffer+4	; save it in the proper place..	iny	iny	lda [SourcePtr],y	; now get the font famNum	xba	sta tempBuffer+2; Now temp buffer has this style info, we must convert it and write it out..	ldy StyleOffset	; where if the style handle to put the data	lda tempBuffer	; add this offset to the start of this paragraph	clc	adc CurrentTextOffset	sta [theStylePtr],y	lda #0	adc CurrentTextOffset+2	iny	iny	sta [theStylePtr],y	iny	iny	lda TempBuffer+2	sta [theStylePtr],y	iny	iny	lda TempBuffer+4	sta [theStylePtr],y; now all the style data is in the style handle, loop back again..	bra @Loop@StyleLoopEnd	ldax StyleHandle	jsr  UnLockIt	; always unlock this when exiting!	rts	; we are done, better return..;AddThisParagraph; This routine will add the characters from sourcePtr into our destination; handle	ldax ResultSize	; make the size the current offset	stax CurrentTextOffset	ldax ResultText	; first unlock the handle so we can grow it	jsr  UnlockIt	lda  [SourcePtr]	; get the number of uncompressed bytes	xba	sta  [SourcePtr]	; save it for later..	clc	adc  ResultSize	sta  ResultSize	bcc  @1	inc  ResultSize+2@1	PushLong ResultSize	PushLong ResultText	_SetHandleSize	; grow the handle to its new size..		ldax ResultText	jsr  DerefIt	stax ResultPtr	; point to the current location in the dest array	; At this point resultPtr now points to the start of our text array and the ; SourcePtr points to our current paragraph. CurrentTextOffset point to where to; start inserting text into the result buffer	ldax ResultPtr	; make resultptr point to the actual insertion point	clc	adc  CurrentTextOffset@2	sta  ResultPtr	; save the low word ..	txa	adc  CurrentTextOffset+2	sta  ResultPtr+2;; Now determine whether to simply copy the text or decompress it..	lda  ThisParaPosition+2	and  #$0800	; mask off compression flag	bne  Decompress;; If we get here the paragraph is not compressed and it can simply be copied	ldax SourcePtr	clc	adc  #2	bcc  @3	inx@3	phx	pha	ldax ResultPtr	phx	pha	pea  $0000	; never more than a bank..	lda  [SourcePtr]	; get the number of characters to decompress	pha	_BlockMove	;; Now set up to read the style information by setting ThisParaStyleStart	lda  [SourcePtr]	; get the number of decompressed bytes of data	inc  a	inc  a	; adjust for the number of bytes..	sta  ThisParaStyleStart	rts;; The following routine will decompress the goofy macwrite compresion schemedecompress	lda  [SourcePtr]	sta  ScratchSize	; save the destination text size	lda  sourcePtr	; bump source pointer by 2..	clc	adc  #2	sta  sourcePtr	bcc  @1	inc  sourcePtr+2@1	lda  #0	; zero out the B part of A	longa Off	sep  #$20	; gotta do it one byte at a time; Now set up the vars for the unpacking loop; <Y> will contain the offset into the resultstring handle; deref+2 will be the nibble flag 0 means high nibble -1 means low; <X> will contain the offset into the sourcePtr; deref will be used to hold <Y> or <X> when we write a byte	ldy  #0	; thats about it...	ldx  #0	stz  deref+2	; our little nibble flag!@UnPackLoop	jsr  GetNibble	; read in the next nibble	cmp  #$000F	; is it a whole byte indicator?	beq  @GetAByte	; if so get the byte; if we get here its a nibble compressed character, better read the thing..	stx  deref	; save <X> for a second..	tax	lda  MyDecriptKey,x	; get the encripted character	ldx  deref	sta  [resultPtr],y	; save the byte;@NextChar	iny	cpy  ScratchSize	blt  @UnPackLoop	; we are done transfering the data?	clc	bra UnPackDone	; if so better return;; This routine is called if the byte we want is not compressed, we must then go out; and fetch the thing@GetAByte	jsr  GetNibble	asl  a	; move it to the high nibble	asl  a	asl  a	asl  a	sta  deref	; save it for a second	jsr  GetNibble	ora  deref	; create the byte	sta  [resultPtr],y	bra  @NextChar	; and scoop up the next character;; This following routine will fetch a nibble from the input stream and return with it; in <A>GetNibble	bit deref+2	; see if deref+2 is negative..	bmi @GetLow	; must get the low nibble if this is so..;; Get High gets the high nibble of the data stream	sty deref+2	; save <Y> for a moment	txy	lda [sourcePtr],y	; get the byte in question	ldy deref+2	; restore <Y>	pha	; save the char for a second	lda #$FF		sta deref+2	; set the low nibble flag	pla	; get the data back	lsr  a	; shift the data over..	lsr  a	lsr  a	lsr  a	rts	; and return;; Gets the low nibble of the data stream and bumps said stream@GetLow	sty deref+2	; save <Y> for a moment	txy	lda [sourcePtr],y	; get the byte in question	ldy deref+2	; restore <Y>	stz deref+2	; reset the high nibble flag	inx	; bump the source stream pointer	and #$0F	; strip the low byte	rtsUnPackDone;; be sure to save the starting location of the style info for this record	lda deref+2	beq @xIsRight	inx@xIsRight	longa on	rep  #$20	; gotta do it one byte at a time	stx  ThisParaStyleStart	clc	rts;; This routine will read the paragraph pointed to by currentParaOffsetReadThisParagraph		lda CurrentParaOffset	clc	adc #8	tay	lda [MainArrayPtr],y	sta ThisParaPosition	iny	iny	lda [MainArrayPtr],y	sta ThisParaPosition+2	iny	iny	lda [MainArrayPtr],y	sta ThisParaLength; resize the scratch handle and deref if needed	cmp ScratchareaSize	beq @NoResize	blt @NoResize		ldax ScratchHandle	jsr UnlockIt	pea 0	lda ThisParaLength	pha	PushLong ScratchHandle	_SetHandleSize	bcs @LocalErr@NoResize	ldax ScratchHandle	jsr  derefIt	stax SourcePtr	; Now read in the data...	lda  ThisParaPosition+2	and  #$00FF	; strip off the status byte	tax	lda  ThisParaPosition	jsr  SetMark	bcs  @LocalErr		ldy  ThisParaLength	ldax SourcePtr	jsr  ReadData	bcs  @LocalErr; data is now read in!	rts@LocalErrLocalError	sta >ThisError	jsr CloseFile	sec	rts	SetStyleHandleSize	pea  0	phy	; new style handle size	sty  StyleSize	; save the current style size..	ldax StyleHandle	phx	pha	jsr unlockIt	; be sure this handle is unlocked.	_SetHandleSize	ldax StyleHandle	jsr  derefIt	stax theStylePtr	rts	UnlockIt	stax deref	ldy #4	lda [deref],y	and #$7FFF	sta [deref],y	rtsderefIt		stax deref	ldy #4	lda [deref],y	ora #$8000	sta [deref],y	ldy #2	lda [deref],y	tax	lda [deref]	rts	ScratchHandle	ds.L 1CurrentTextOffset	ds.L 1CurrentParaOffset	ds.W 1ThisParaPosition	ds.L 1ThisParaLength	ds.W 1ThisParaStyleStart	ds.W 1ThisParaStyleSize	ds.W 1ScratchSize	ds.W 1ResultSize	ds.L 1ScratchOffset	ds.W 1ScratchAreaSize	ds.W 1RulerFlag	ds.W 1	EndP		EJECT********************************************************************************ReadMACAWORD	PROC Export* Function ReadMACAWORD(theDecript:Handle; theFileName:ptr):handle;* Description:	reads a given Macwrite data file*** Inputs:	On stack** Outputs:	on stack** External Refs:** Entry Points:********************************************************************************	With MacRezGlobals 	phd	; save old dpage and bank	phb		pha	pha	pha	pha		tsc	tcd	; set up our stack frame		phk	; set up our data banl	plb		stz  resultText	; zero out the result	stz  resultText+2	lda  #0	sta  >ThisError	; and zero out the error code		jsr  OpenFile	; lets get this baby moving!	bcc  NoOpenError	sta  >ThisError	bra  CallFinished	NoOpenError	jsr  GetMainArrayInfo	bcsL CallFinished		jsr  ReadMainArray	; load the main array into memory	bcs  CallFinished		jsr  ReadTheText	bcs  CallFinished		jsr  CloseFile	; Undo the stack stuffCallFinished	pla	pla	pla	pla		plb	pld	longa off	sep #$20	pla	ply		plx	plx	plx	plx	plx	plx		phy	pha		longa On	rep #$20	rtl	EndP********************************************************************************	MyOOMRtn*	This header record must be directly before MyOOM routine*	in memory.*******************************************************************************MyOOMRtn	RECORD Export	dc.L 0	;used by queue manager	dc.W 0	;OOMEntry version	dc.W $A55A	;queue entry signature	EndR********************************************************************************MyOOM	PROC* Function MyOOM(stage: Integer; bytesNeeded: Longint):LongInt;* Description:	This routine will release memory when it is called, if*	the stage is 1.  ** Inputs:	urgence level: Integer; # of bytes needed: Longint;** Outputs:	number of bytes freed: Longint;** External Refs:	handle to reserve memory: Handle;** Entry Points:	MyOOM only, please.********************************************************************************	import ReserveHndl	import OOMFlagRTLAdr	equ 1Stage	equ RTLAdr+3BytesNeeded	equ Stage+2Result	equ BytesNeeded+4;;  Zero out the result before starting.;	lda #0	sta Result,s	sta Result+2,s;;  Since this routine can be called before and after memory is purged,;  we want to wait 'til after everything is purged and things are really;  getting bad.  So we check the stage parameter.;	lda stage,s	beq OOMEnd;;  We know the memory manager has tried everthing else and still needs;  more memory.  Now we need to make sure that we haven't already freed;  the memory.;	lda >OOMFlag	bne OOMEnd;;  Now we free the memory and set the OOMFlag to notify other routines;  that can alert the user that memory is very tight.;	PushLong >ReserveHndl	_DisposeHandle	lda #1	sta >OOMFlag		lda #$4000	sta Result,s;;  Now clean up the stack and return to the memory manager.;OOMEnd		LongA Off	sep #$20		pla	ply		plx	plx	plx		phy	pha		LongA On	rep #$20		RTL		EndP********************************************************************************SaveDB	PROC export* Function SaveDB:Integer;* Description:	This routine sets the data bank register to point to*	the ~globals data segment.  It returns the current DB.* Inputs:	None* Outputs:	Current data bank register: Integer(the number is in the high byte)* External Refs:	ThisError(using only the high word of it's address)********************************************************************************		phb	lda #^ThisError     ; Get the hi-word of "ThisError", which is in ~globals	pha	plb	pla	sta 4,s	rtl		EndP********************************************************************************RestoreDB	PROC export* Function RestoreDB(theSavedDB:Integer);* Description:	This routine sets the data bank register to the value*	of the number passed.  The number is in the high byte.* Inputs:	The saved data bank register value.* Outputs:	none* External Refs:	none********************************************************************************		lda 4,s	pha	plb	plb	lda 2,s	sta 4,s	lda 1,s	sta 3,s	pla	rtl		EndP**************************************************************************   GetDialog640**   This record is all of the templates needed to implement a custom*   Standard File dialog that includes radio buttons for selecting the*   type of file to import.*************************************************************************	case on	case objectGetDialog640	record export	dc.w 0,0,144,400	dc.w -1	dc.w 0,0	dc.l OpenBut640	dc.l CloseBut640	dc.l NextBut640	dc.l CancelBut640	dc.l Scroll640	dc.l Path640	dc.l Files640	dc.l Prompt640	dc.l GetAllTypes	dc.l GetAppleWorks	dc.l GetAWorksGS	dc.l GetMacWrite	dc.l 0	OpenBut640	dc.w 1	dc.w 61,265,73,375	dc.w ButtonItem	dc.l OpenStr	dc.w 0,0	dc.l 0	OpenStr	dc.b 4,'Open'CloseBut640	dc.w 2	dc.w 79,265,91,375	dc.w ButtonItem	dc.l CloseStr	dc.w 0,0	dc.l 0	CloseStr	dc.b 5,'Close'NextBut640	dc.w 3	dc.w 25,265,37,375	dc.w ButtonItem	dc.l DriveStr	dc.w 0,0	dc.l 0	;DriveStr	dc.b 7,'Volumes'DriveStr	dc.b 5,'Disks'	;25-Mar-92 DALCancelBut640	dc.w 4	dc.w 97,265,109,375	dc.w ButtonItem	dc.l CancelStr	dc.w 0,0	dc.l 0	CancelStr	dc.b 6,'Cancel'Scroll640	dc.w 5	dc.w 43,265,55,375	dc.w ButtonItem	dc.l AcceptStr	dc.w 0,0	dc.l 0	AcceptStr	dc.b 6,'Accept'Path640	dc.w 6	dc.w 12,15,24,395	dc.w UserItem	dc.l 0	dc.w 0,0	dc.l 0	Files640	dc.w 7	dc.w 25,18,107,215	dc.w UserItem+ItemDisable	dc.l 0	dc.w 0,0	dc.l 0	Prompt640	dc.w 8	dc.w 3,15,12,395	dc.w UserItem+ItemDisable	dc.l 0	dc.w 0,0	dc.l 0	GetAllTypes	dc.w 101	dc.w 130,210,140,390	dc.w radioItem	dc.l AllTy